    async def create_responder(
        self,
        *,
        account: str,
        content: str,
        copy: bool,
        domain: str,
        copy_to: str | None = None,
        from_: Instant | None = None,
        to: Instant | None = None,
    ) -> EmailDomainTaskSpecialAccount:
        """
        POST /1.0/email/domain/{domain}/responder

        Create a responder

        Args:
            account: Account of domain
            content: Content of responder
            copy: If false, emails will be dropped. If true and copyTo field is empty,
                emails will be delivered to your mailbox. If true and copyTo is set with
                an address, emails will be delivered to this address
            copy_to: Account where copy emails
            domain: Name of your domain name
            from_: Date of start responder
            to: Date of end responder
        """
        data = await self._client.request_json(
            "POST",
            self._client.path("/1.0/email/domain/{domain}/responder", domain=domain),
            body={
                "account": account,
                "content": content,
                "copy": copy,
                "copyTo": copy_to,
                "from": from_,
                "to": to,
            },
        )
        return EmailDomainTaskSpecialAccount.model_validate(data)

